/**
 * Study-to-Quest DEMO content. Static, hand-written sample lessons and a fixed
 * question bank. Nothing here is uploaded, parsed, generated by AI or persisted.
 */
import type { Language, Question, QuestionType, SubjectId } from "@/domain/types";

export interface DemoSection {
  id: string;
  heading: string;
  body: string[];
  example: string;
  keyPoints: string[];
  /** Exactly one bank question per question type. */
  bank: Record<QuestionType, Question>;
}

export interface DemoLesson {
  id: string;
  title: string;
  subjectId: SubjectId;
  topic: string;
  language: Language;
  readMinutes: number;
  summary: string;
  objectives: string[];
  sections: DemoSection[];
}

